code.PricingStrategy.calculateTokenAmount(uin:
function calculateTokenAmount(uint weiAmount) public constant returns (uint tokenAmount) {
 uint bonusRate = 0;
 if (weiAmount >= minimumWeiAmount) {
 if (now < newRateTime) {
 bonusRate = rate1;
 } else {
 bonusRate = rate2;
 }
 }
 return weiAmount.mul(bonusRate);
 }

code.PricingStrategy.PricingStrategy(uint256,:
function PricingStrategy(
 uint _newRateTime,
 uint _rate1,
 uint _rate2,
 uint _minimumWeiAmount
 ) {
 require(_newRateTime > 0);
 require(_rate1 > 0);
 require(_rate2 > 0);
 require(_minimumWeiAmount > 0);
 newRateTime = _newRateTime;
 rate1 = _rate1;
 rate2 = _rate2;
 minimumWeiAmount = _minimumWeiAmount;
 }

code.SafeMath.sub(uint256,uint256):
function sub(uint256 a, uint256 b) internal constant returns (uint256) {
 assert(b <= a);
 return a - b;
 }

code.SafeMath.div(uint256,uint256):
function div(uint256 a, uint256 b) internal constant returns (uint256) {
 uint256 c = a / b;
 return c;
 }

code.SafeMath.mul(uint256,uint256):
function mul(uint256 a, uint256 b) internal constant returns (uint256) {
 uint256 c = a * b;
 assert(a == 0 || c / a == b);
 return c;
 }

code.SafeMath.add(uint256,uint256):
function add(uint256 a, uint256 b) internal constant returns (uint256) {
 uint256 c = a + b;
 assert(c >= a);
 return c;
 }
